import React, { useState, useEffect, useCallback, useRef } from "react";
import { useNavigate } from "react-router-dom";
import "./../styles/Profil.css";

const Profile = () => {
    const [profile, setProfile] = useState(null);
    const [loading, setLoading] = useState(true);
    const [editing, setEditing] = useState({ phone: false, about: false });
    const [draft, setDraft] = useState({ phone: "", about: "" });
    const fileInputRef = useRef(null);
    const navigate = useNavigate();

    const loadProfile = useCallback(async () => {
        setLoading(true);
        try {
            const token = localStorage.getItem("token");
            const res = await fetch("/profile", {
                headers: { Authorization: `Bearer ${token}` },
            });

            if (res.status === 404) return navigate("/app/setup-profile");
            if (res.status === 401 || res.status === 403) return navigate("/");
            if (!res.ok) throw new Error("Eroare necunoscută la fetch profil");

            const data = await res.json();
            setProfile(data);
            setDraft({ phone: data.phone || "", about: data.about || "" });
        } catch (err) {
            console.error(err);
        } finally {
            setLoading(false);
        }
    }, [navigate]);

    useEffect(() => {
        loadProfile();
    }, [loadProfile]);

    const updateProfile = async (changes) => {
        try {
            const token = localStorage.getItem("token");
            const res = await fetch("/profile", {
                method: "PUT",
                headers: {
                    "Content-Type": "application/json",
                    Authorization: `Bearer ${token}`,
                },
                body: JSON.stringify({ ...profile, ...changes }),
            });
            if (!res.ok) throw new Error("Update failed");
            await loadProfile(); // ✅ refetch profile after update
        } catch (err) {
            console.error("Eroare la actualizare:", err);
        }
    };

    // ✅ Upload poza
    const handleFileUpload = async (file) => {
        try {
            const token = localStorage.getItem("token");
            const formData = new FormData();
            formData.append("file", file);

            const res = await fetch("/profile/photo", {
                method: "POST",
                headers: { Authorization: `Bearer ${token}` },
                body: formData,
            });

            if (!res.ok) throw new Error("Upload failed");
            await loadProfile(); // ✅ refetch profile after upload
        } catch (err) {
            console.error("Eroare la upload poza:", err);
        }
    };

    if (loading) return <div>Loading…</div>;
    if (!profile) return null;

    return (
        <div className="profile-wrapper">
            <h1 className="profile-title">MY PROFILE</h1>
            <div className="profile-sections">
                <div className="profile-left">
                    <div className="card profile-main-card">
                        <div className="profile-header">
                            <img
                                src={profile.profilePictureUrl || "/avatar.jpg"}
                                alt="Avatar"
                                className="profile-avatar"
                                onClick={() => fileInputRef.current?.click()} // ✅ click pe poza
                                style={{ cursor: "pointer" }}
                            />
                            <input
                                type="file"
                                accept="image/*"
                                style={{ display: "none" }}
                                ref={fileInputRef}
                                onChange={(e) => {
                                    if (e.target.files[0]) handleFileUpload(e.target.files[0]);
                                }}
                            />
                            <button onClick={() => fileInputRef.current?.click()}>
                                Upload Photo
                            </button>
                        </div>

                        <div className="info-group">
                            <InfoRow label="Your First Name" value={profile.firstName} />
                            <InfoRow label="Your Last Name" value={profile.lastName} />
                            <InfoRow label="Email" value={profile.email} />

                            <div className="info-item">
                                <span className="label">Phone Number</span>
                                {!editing.phone ? (
                                    <div className="value-edit">
                                        <span>{profile.phone}</span>
                                        <button onClick={() => setEditing({ ...editing, phone: true })}>
                                            Edit
                                        </button>
                                    </div>
                                ) : (
                                    <EditField
                                        type="text"
                                        value={draft.phone}
                                        onChange={(v) => setDraft({ ...draft, phone: v })}
                                        onSave={() => {
                                            updateProfile({ phone: draft.phone });
                                            setEditing({ ...editing, phone: false });
                                        }}
                                        onCancel={() => setEditing({ ...editing, phone: false })}
                                    />
                                )}
                            </div>

                            <div className="info-item">
                                <span className="label">Password</span>
                                <button onClick={() => navigate("/app/reset-password")}>
                                    Reset Password
                                </button>
                            </div>
                        </div>
                    </div>

                    <div className="card">
                        <div className="info-item header-row">
                            <span className="label">About (Optional)</span>
                            {!editing.about && (
                                <button onClick={() => setEditing({ ...editing, about: true })}>
                                    Edit
                                </button>
                            )}
                        </div>

                        {!editing.about ? (
                            <p>{profile.about}</p>
                        ) : (
                            <EditTextarea
                                value={draft.about}
                                onChange={(v) => setDraft({ ...draft, about: v })}
                                onSave={() => {
                                    updateProfile({ about: draft.about });
                                    setEditing({ ...editing, about: false });
                                }}
                                onCancel={() => setEditing({ ...editing, about: false })}
                            />
                        )}
                    </div>

                    <div className="card">
                        <div className="info-item">
                            <span className="label">Two-Factor Authentication</span>
                            <button onClick={() => navigate("/app/setup-2fa")}>
                                {profile.twoFactorEnabled ? "Manage 2FA" : "Enable 2FA"}
                            </button>
                        </div>
                    </div>

                    <div className="card">
                        <InfoRow label="KYC Status" value={<span>{profile.kycStatus}</span>} />
                        <InfoRow label="KYC Details" value={<button>View</button>} />
                    </div>

                    <div className="card">
                        <InfoRow label="Bank details" value={<button>View</button>} />
                    </div>
                </div>

                <div className="profile-right">
                    <div className="card">
                        <InfoRow label="Current Status" value="⭐" />
                    </div>

                    <div className="card">
                        <span className="label">Expertise In</span>
                        <div className="tags">
                            {profile.expertise?.map((tag, i) => (
                                <span key={i} className="tag">{tag}</span>
                            ))}
                        </div>
                    </div>

                    <div className="card">
                        <InfoRow label="Current Year" value={profile.currentYear} />
                        <InfoRow label="Rating" value={`${profile.rating}/10`} />
                    </div>

                    <div className="card">
                        <span className="label">Your Achievements</span>
                        <ul>
                            {profile.achievements?.map((a, i) => (
                                <li key={i}>{a}</li>
                            ))}
                        </ul>
                    </div>
                </div>
            </div>
        </div>
    );
};

const InfoRow = ({ label, value }) => (
    <div className="info-item">
        <span className="label">{label}</span>
        {typeof value === "string" ? <span>{value}</span> : value}
    </div>
);

const EditField = ({ type, value, onChange, onSave, onCancel }) => (
    <div className="value-edit">
        <input type={type} value={value} onChange={(e) => onChange(e.target.value)} />
        <button onClick={onSave}>Save</button>
        <button onClick={onCancel}>Cancel</button>
    </div>
);

const EditTextarea = ({ value, onChange, onSave, onCancel }) => (
    <div>
        <textarea value={value} onChange={(e) => onChange(e.target.value)} />
        <div>
            <button onClick={onSave}>Save</button>
            <button onClick={onCancel}>Cancel</button>
        </div>
    </div>
);

export default Profile;
